UPDATE sn_item SET factory_code = #{g.org}, pi_no = #{g.pi}, customer_code = #{g.customer}, bill_no = #{g.bill},
  bill_seq = #{g.seq}, material_code = #{g.material}, rev = rev + 1, status = #{g.status}, push_type = #{g.pushType},
  delivery_mode = #{g.mode}, delivery_batch_no = NULL, transfer_kind = #{tkind}, transfer_doc_no = #{docNo},
  transfer_from_org = IF(#{g.keepFrom}, transfer_from_org, #{g.fromOrg}), updated_at = #{now}
WHERE id IN #{i}

