  , rev = rev + 1, status = 'TO_PUSH', push_type = 'REASSIGN', delivery_batch_no = NULL,
    transfer_kind = NULL, transfer_doc_no = NULL, transfer_from_org = NULL
  , rev = rev + 1

, updated_at = #{now}
WHERE id IN #{i}
